    /// @dev UPV4 trusts the payer commitment O4 stores, so a policy must reject one it cannot vouch for.
    /// @return takerWhitelisted Whether the intent settles without the settlement policy
    /// @return arbitrator Address that may release, cancel and extend the intent; zero for none
    function validateSignalIntent(address taker, IOrchestratorV4.SignalIntentParams calldata params)
        external
        returns (bool takerWhitelisted, address arbitrator);
}
